function destinationForms(root) {
  const drive = /^([A-Za-z]):[\\/](.*)$/u.exec(root);
  assert.ok(drive?.[1] && drive[2] !== undefined);
  return Object.freeze({
    cmd: `${drive[1].toUpperCase()}:\\${drive[2].replaceAll("/", "\\")}`,
    shell: `/mnt/${drive[1].toLowerCase()}/${drive[2].replaceAll("\\", "/")}`,
  });
}

function countOccurrences(text, needle) {
  assert.ok(needle.length > 0);
  return text.split(needle).length - 1;
}

function inspectInstalledTree(packageRoot) {
  const tree = capturePackTreeIdentity(packageRoot);
  const files = tree.entries.filter((entry) => entry.kind === "file");
  const hardlinks = files.filter((entry) => String(entry.nlink) !== "1");
  const roster = files.filter((entry) => entry.path.startsWith("node_modules/.bin/"))
    .map((entry) => entry.path);
  assert.deepEqual(roster, SHIMS);
  const forms = destinationForms(destination);
  const occurrenceByShim = Object.fromEntries(roster.map((logical) => {
    const body = readFileSync(join(packageRoot, ...logical.split("/")), "utf8");
    const expected = logical.endsWith(".CMD") ? forms.cmd : forms.shell;
    return [logical, countOccurrences(body, expected)];
  }));
